/* EM27 design prototype. Sample mechanics, not the production simulation. */
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const screens={week:'01 · Week / planning',title:'00 · Title / new game',empty:'02 · Inbox / empty',overbooked:'03 · Calendar / overbooked',event:'04 · Event / must respond',long:'05 · Event / long copy',ignored:'06 · Event / ignored',squad:'07 · Squad list',player:'08 · Player card',projects:'09 · Projects',assign:'10 · Project assignment',office:'11 · Office', 'friday-good':'12 · Friday / good','friday-bad':'13 · Friday / bad',loading:'14 · Friday / slow generation','back-good':'15 · Back page / good','back-bad':'16 · Back page / bad',checkin:'17 · Mid-quarter / week 6',review:'18 · Quarterly review',kit:'19 · UI kit',splash:'20 · Splash screen'};
const people=[{n:'Priya Nair',r:'L5 · Senior Engineer',v:[17,12,11,18,6,10],tenure:'3y',bio:'Knows where the bodies are buried in the build pipeline.'},{n:'Tom Ellis',r:'L4 · Engineer',v:[13,14,15,11,14,16],tenure:'2y',bio:'Writes the runbook before anyone knows they need it.'},{n:'Dana Okafor',r:'L3 · Engineer',v:[12,8,14,16,11,7],tenure:'8mo',bio:'Still says yes to every meeting invitation.'},{n:'Mei Chen',r:'L5 · Senior Engineer',v:[18,17,12,13,15,14],tenure:'4y',bio:'Turns an incident into a very short postmortem.'},{n:'Alex Rivera',r:'L4 · Engineer',v:[14,11,17,12,13,15],tenure:'1y',bio:'Can explain the architecture without a diagram.'},{n:'Sam Patel',r:'L4 · Engineer',v:[15,13,10,15,12,13],tenure:'2y',bio:'The person quietly keeping the migration alive.'}];
const events=[
{from:'Priya Nair',role:'Senior Engineer · L5',title:'“Got a sec?”',cat:'PEOPLE',required:true,body:'Priya’s calendar shows a 45-minute “dentist appointment” for the third time this month. She asks whether her promo packet is still happening this cycle.',ignore:'A required conversation. Pick an intent to continue.',choices:[['Commit to the promo, in writing',1,'Morale ↑ · Promise due wk 10'],['Be honest: budget is frozen until Q2',2,'Morale ↓ · Trust ↑'],['Offer tech lead on the new project',1,'Ambition ✓ · Project risk']]},
{from:'Dana Okafor',role:'Engineer · L3',title:'The pager is still in my dreams',cat:'PEOPLE',body:'Dana has been on call twice in three weeks. “I’m fine” arrives at 02:14. She is also assigned to the migration.',ignore:'Energy ↓ · Burnout risk',choices:[['Book a proper check-in',1,'Energy ↑ · Morale ↑'],['Take her off the critical path',0,'Energy ↑ · Delivery ↓'],['Pair on the runbook',2,'Debugging ↑ · On-call load ↓']]},
{from:'Jules Park',role:'Product Manager',title:'One small addition to scope',cat:'DELIVERY',body:'The demo needs a live dashboard. Jules says it’s “basically the same data, just in a different shape.” The deadline has not moved.',ignore:'Scope stays fixed · PM Trust ↓',choices:[['Negotiate the scope',2,'Deadline protected · PM Trust ↑'],['Agree to the dashboard',1,'Scope ↑ · Delivery risk'],['Delegate the tradeoff to Alex',0,'Communication matters · Alex Energy ↓']]},
{from:'Morgan Vale',role:'Skip-level',title:'A quick deck for the QBR',cat:'POLITICS',body:'“Nothing fancy. Five slides on impact, risks, headcount, the roadmap and the roadmap’s roadmap. Before Thursday?”',ignore:'Skip-level Trust ↓',choices:[['Build the five-slide version',2,'Skip-level Trust ↑ · 2 slots'],['Send the existing weekly update',0,'Time saved · Trust risk'],['Push back on the timing',1,'Stress ↓ · Political Capital ↓']]},
{from:'The CEO',role:'Office of the CEO',title:'What if it had an AI button?',cat:'POLITICS',body:'A forwarded screenshot, no context. “Can we get something like this in for the demo?” The screenshot is from a completely different industry.',ignore:'May fade away · No guaranteed cost',choices:[['Write a small exploration doc',2,'Visibility ↑ · Delivery risk'],['Ask Jules to triage',0,'PM Energy ↓ · Time saved'],['Build a throwaway prototype',3,'CEO satisfied · Tech Debt ↑']]},
{from:'Rae Cooper',role:'Recruiting partner',title:'A great candidate. One more loop.',cat:'PEOPLE',body:'The candidate can only interview on Thursday, which is also when every other thing is happening.',ignore:'Candidate may move on',choices:[['Join the final interview',1,'Hiring pipeline ↑'],['Delegate to Mei',0,'Mei Energy ↓ · Time saved']]}
];
const defaults=()=>({week:4,company:'Vercel',choices:{3:0},books:{1:true},focus:false,assign:[0,0,1,2,1,2],oncall:2,capital:24,politics:[],reviewOpen:false,checkin:0,level:'EM',quarter:1,reputation:62,firings:0,history:[],packet:6,postmortem:false,reviewOutcome:'stay',offerKind:'poach',runEnd:'win',roster:null});
let state=defaults(),saved=false,storageOK=true;try{const s=JSON.parse(localStorage.getItem('em27.design.v1'));if(s?.week&&s?.choices&&s?.books&&Array.isArray(s.assign)){state={...defaults(),...s};saved=true}}catch(e){storageOK=false}
let screen='week',eventId=0,personId=0,projectId=0,fridayCount=0,fridayTimer=null,fridayBad=false,theme='light';
try{theme=localStorage.getItem('em27.design.theme')||(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light')}catch(e){}
document.documentElement.dataset.theme=theme;
function save(){try{localStorage.setItem('em27.design.v1',JSON.stringify(state));saved=true}catch(e){storageOK=false}}
function notify(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('show'),2800)}
function cost(){return Object.values(state.books).filter(Boolean).length+(state.focus?1:0)+Object.entries(state.choices).reduce((n,[id,c])=>n+(c==='ignore'?0:events[id].choices[c][1]),0)}
function required(){return state.choices[0]===undefined}
const num=(v)=>`<span class="num ${v<=7?'bad':v<=13?'warn':'good'}">${v}</span>`;
const badge=(n)=>`<span class="badge" data-company="${n}">${n==='Vercel'?'VE':n==='Stripe'?'ST':'GO'}</span>`;
const meter=(value,label)=>`<div class="meter" role="meter" aria-label="${label}" aria-valuenow="${value}" aria-valuemin="0" aria-valuemax="100"><b style="width:${value}%"></b></div>`;
const btn=(label,action,cls='secondary')=>`<button class="${cls}" data-action="${action}">${label}</button>`;
function calendar(used=cost()){return `<section class="calendar" aria-label="Calendar budget"><div class="cal-head"><span class="eyebrow">WEEK ${state.week} / YOUR CALENDAR</span><span class="cal-value ${used>8?'bad':''}">${used>8?`${used-8} OVERBOOKED`:`${8-used} OF 8 LEFT`}</span></div><div class="slots" aria-label="${used} slots used, 8 available">${Array.from({length:Math.max(8,used)},(_,i)=>`<span class="slot ${i<used?'filled':''} ${i>=8?'extra':''}">${i<used?(i>=8?'+':'■'):'·'}</span>`).join('')}</div><div class="cal-foot"><span>${used>8?'! Extra time adds Stress':`${used} booked · ${8-used} available`}</span><button data-action="agenda">View bookings ↓</button></div></section>`}
function header(){return `<div class="window-caption"><span>▣ Engineering Manager 2027</span><span aria-hidden="true">▱ □ ×</span></div><header class="topbar"><div class="brand">${screen==='player'?people[personId].n:'EM27'}<span class="edition">${screen==='player'?people[personId].r.toUpperCase():'ENGINEERING MANAGER'}</span></div><div class="company">${badge(state.company)} ${state.company}</div></header><div class="season"><span>Q1 / SEASON 2027</span><span>WEEK ${String(state.week).padStart(2,'0')} OF 12 · MON</span></div>`}
const paths={Week:'M3 5h14v12H3z M6 2v5m8-5v5M3 9h14',Squad:'M6 9a3 3 0 1 0 0-6 3 3 0 0 0 0 6Zm8-1a2 2 0 1 0 0-4 2 2 0 0 0 0 4ZM1 18v-3a5 5 0 0 1 10 0v3m2-7a4 4 0 0 1 6 4v3',Projects:'M2 5h6l2 2h8v10H2z',Office:'M4 18V3h12v15M1 18h18M7 6h2m2 0h2M7 10h2m2 0h2M8 18v-4h4v4'};
function dock(){let active=['event','long','ignored','empty','overbooked'].includes(screen)?'week':screen==='player'?'squad':screen==='assign'?'projects':screen;return `<footer class="dock"><p class="dock-note">${required()?'! 1 must-respond item before Friday':`${cost()}/8 slots booked · ${Object.keys(state.choices).length}/6 demands decided`}</p><button class="primary" data-action="continue">${required()?'Respond to Priya to continue':'Continue to Friday →'}</button><nav aria-label="Main navigation">${Object.keys(paths).map(n=>`<button class="tab ${active===n.toLowerCase()?'active':''}" data-screen="${n.toLowerCase()}" ${active===n.toLowerCase()?'aria-current="page"':''}><svg viewBox="0 0 20 20" aria-hidden="true"><path d="${paths[n]}"></path></svg>${n}</button>`).join('')}</nav></footer>`}
function agenda(){return `<div id="agenda"><div class="section-head"><span>BOOKED TIME</span><span>${cost()} / 8</span></div><div class="panel">${Object.entries(state.choices).filter(([i,c])=>c!=='ignore'&&events[i].choices[c][1]>0).map(([i,c])=>`<div class="agenda-row"><span>${esc(events[i].from)} · ${events[i].choices[c][1]} slots</span><button data-event="${i}">Change</button></div>`).join('')}${Object.keys(state.books).filter(i=>state.books[i]).map(i=>`<div class="agenda-row"><span>1:1 · ${people[i].n} · 1 slot</span><button data-unbook="${i}">Refund</button></div>`).join('')}${state.focus?`<div class="agenda-row"><span>Focus time · 1 slot</span><button data-action="focus">Refund</button></div>`:''}${cost()===0?'<div class="agenda-row">Your calendar is clear. For now.</div>':''}</div>${!state.focus?btn('＋ Book focus time · 1 slot','focus'):''}</div>`}
function week(empty=false){return `<div class="heading"><h1>The week ahead.</h1><small>MONDAY</small></div><p class="subtitle">Six demands. Eight slots. Something has to give.</p>${cost()>8?`<div class="notice danger"><b>Overbooked by ${cost()-8} slots.</b><p>You can continue. Extra time adds Stress and may shrink next week’s calendar. Refund a booking below to recover time.</p></div>`:''}${empty?`<div class="panel empty"><div class="empty-icon">[ ✓ ]</div><h2>Decisions made.</h2><p>You do not have to fill every slot. Review staffing, then let the week play out.</p>${btn('Review projects →','projects')}</div>`:`<div class="section-head"><span>INBOX / 6 DEMANDS</span><span>${events.filter((_,i)=>state.choices[i]===undefined).length} UNDECIDED</span></div><div class="panel">${events.map((e,i)=>{const c=state.choices[i];return `<button class="inbox-row ${e.required&&c===undefined?'required':''} ${c!==undefined&&c!=='ignore'?'done':''} ${c==='ignore'?'ignored':''}" data-event="${i}"><span class="row-meta"><span>${e.from}</span><span>${c==='ignore'?'0 slots':c!==undefined?`${e.choices[c][1]} slots`:`${e.required?Math.min(...e.choices.map(c=>c[1])):0}–${Math.max(...e.choices.map(c=>c[1]))} slots`}</span></span><span class="row-title">${esc(e.title)}</span><span class="row-tags">${e.required&&c===undefined?'! MUST RESPOND':c==='ignore'?'↷ IGNORED · resolves Friday':c!==undefined?`✓ ${esc(e.choices[c][0])}`:e.cat}</span></button>`}).join('')}</div>`}${agenda()}<p class="save-status">${storageOK?'✓ Plan saved on this device':'Local storage unavailable. Keep this tab open.'}</p>`}
function eventView(long=false){const e=events[eventId],selected=state.choices[eventId];return `${btn('← Back to week','week','back')}<div class="split"><span class="eyebrow">${e.cat} / ${eventId+1} OF 6</span>${e.required?'<span class="mini bad">! MUST RESPOND</span>':''}</div><div class="sender"><span class="avatar">${e.from.split(' ').slice(0,2).map(n=>n[0]).join('')}</span><div><b>${e.from}</b><small>${e.role}</small></div></div><h1>${long?'“Can we talk about the promotion packet, the new project, and what you meant by ‘next cycle’?”':esc(e.title)}</h1><p class="situation">${long?`${e.body} She has already drafted the impact document, collected six peer reviews, and taken over the work that was supposed to demonstrate her readiness. “I’m trying to work out whether next cycle is a date or a feeling.”`:e.body}</p>${selected!==undefined?`<div class="notice ${selected==='ignore'?'':'success'}"><b>${selected==='ignore'?'↷ Marked to ignore':'✓ Intent booked'}</b><p>${selected==='ignore'?e.ignore:'Reversible until Continue. Choosing another intent refunds the old slot cost.'}</p></div>`:''}<div class="section-head"><span>CHOOSE YOUR INTENT</span><span>COST / HINTS</span></div>${e.choices.map((c,i)=>`<button class="intent ${selected===i?'selected':''}" data-choice="${i}" aria-pressed="${selected===i}"><span class="intent-main"><span>${selected===i?'✓ ':''}${long&&i===0?'Commit to the promotion in writing, reserve time to draft her packet, and tell her exactly which review it will enter':esc(c[0])}</span><span class="cost">${c[1]} ${c[1]===1?'slot':'slots'}</span></span><span class="intent-hints">${c[2]}</span></button>`).join('')}<button class="intent ignore" data-choice="ignore" ${e.required?'disabled':''}><span class="intent-main"><span>${e.required?'Ignore unavailable':'↷ Ignore this demand'}</span><span class="cost">0 slots</span></span><span class="intent-hints">${e.ignore}</span></button><p class="helper">Your choice spends time, not a guaranteed outcome. Hints show likely direction. Numbers resolve on Friday.</p>${selected!==undefined?btn('Done · back to inbox →','week','primary'):''}`}
function squad(){return `<div class="heading"><h1>Your squad.</h1><small>6 / 6 ENGINEERS</small></div><p class="subtitle">Know your people. Especially the quiet ones.</p><div class="roster-head"><span>ENGINEER / ASSIGNMENT</span><span>COD</span><span>DBG</span><span>MOR</span><span>ENG</span></div><div class="panel">${people.map((p,i)=>`<button class="engineer" data-person="${i}"><span class="person">${p.n}<small>${p.r.split(' · ')[0]} · ${['Checkout v2','API migration','Build reliability'][state.assign[i]]}${state.oncall===i?' · ON CALL':''}</small></span>${num(p.v[0])}${num(p.v[1])}${num(p.v[4])}<span class="energy">${p.v[5]}<i><b style="width:${p.v[5]*5}%"></b></i></span></button>`).join('')}</div><div class="section-head"><span>READING THE NUMBERS</span><span>1–20</span></div><p class="helper"><span class="bad">1–7 low</span> · <span class="warn">8–13 capable</span> · <span class="good">14–20 strong</span><br>Tap an engineer for their full attributes and history.</p><div class="notice"><b>Dana’s energy is 7/20.</b><p>On-call duty drains Energy. Check Projects before locking the rotation.</p></div>`}
function player(){const p=people[personId];return `${btn('← Squad','squad','back')}<nav class="profile-tabs" aria-label="Player sections"><button data-action="player-profile" class="selected">Profile</button><button data-action="player-history">History</button><button data-action="player-actions">Actions</button></nav><p class="player-meta">${p.r} · ${p.tenure} tenure</p><p class="subtitle">${p.bio}</p><div class="panel">${['Coding','Debugging','Communication','Ambition','Morale','Energy'].map((a,i)=>`${i===0||i===3||i===4?`<div class="attr-group">${i===0?'Skills':i===3?'Drive':'Condition'}</div>`:''}<div class="attr"><span>${a}</span>${num(p.v[i])}</div>`).join('')}<div class="attr-group">Scouting</div><div class="attr"><span>Loyalty</span><span class="num">?</span></div></div><p class="helper">Loyalty stays hidden until discovered through 1:1s.</p><div class="section-head"><span>DISCOVERED TRAITS</span></div><span class="trait">${personId===0?'Wants to lead':personId===3?'Quiet genius':'No traits discovered'}</span><div class="section-head"><span id="player-history">WHY THESE NUMBERS?</span></div><div class="panel"><div class="why"><b class="bad">${personId===0?'Morale −3':'Energy −2'}</b><small>${personId===0?'Promo deferred · week 2':'Release support · week 3'}</small></div><div class="why"><b class="${personId===0?'bad':'good'}">${personId===0?'Energy −4':'Morale +1'}</b><small>${personId===0?'On call during outage · week 3':'Peer recognition · week 2'}</small></div></div><div class="section-head"><span id="player-actions">ACTIONS</span><span>UNTIL CONTINUE</span></div><button class="intent" data-book="${personId}"><span class="intent-main"><span>${state.books[personId]?'✓ 1:1 booked · tap to refund':'Book a 1:1'}</span><span class="cost">1 slot</span></span><span class="intent-hints">Morale ↑ · Chance to reveal a trait</span></button><button class="secondary" data-oncall="${personId}">${state.oncall===personId?'✓ On call this week':'Set on call · 0 slots'}</button><details><summary style="min-height:44px;padding:12px 0;color:var(--muted);font-size:12px;cursor:pointer">People operations</summary><p class="helper">Promotion, PIP, hiring and dismissal need budget, evidence and deliberate review. Decision flows are specified in the handoff; controls below illustrate unavailable states.</p><button class="secondary" disabled>Promote · headcount budget frozen</button><button class="secondary" disabled>PIP · evidence review required</button><button class="secondary" disabled>Dismiss · review required</button><button class="secondary" disabled>Hire · no open requisition</button></details>`}
const projectsData=[['Checkout v2','Jules Park · PM',68, 'WEEK 6', 'On track'],['API migration','Morgan Vale · Skip-level',34,'WEEK 7','At risk'],['Build reliability','Casey Lin · Peer EM',45,'WEEK 9','On track']];
function projects(){return `<div class="heading"><h1>Delivery desk.</h1><small>3 ACTIVE</small></div><p class="subtitle">The deadline is a date. The estimate is a belief.</p><div class="panel">${projectsData.map((p,i)=>`<section class="project"><div class="split"><h2>${p[0]}</h2><span class="mini ${i===1?'bad':'good'}">${p[4]}</span></div><p class="mini">${p[1]} · DUE ${p[3]}</p><div class="meter" role="meter" aria-label="${p[0]} progress" aria-valuenow="${p[2]}" aria-valuemin="0" aria-valuemax="100"><b style="width:${p[2]}%"></b><span class="deadline" title="Expected progress by now"></span></div><div class="split mini"><span>${p[2]} / 100 POINTS</span><span>│ EXPECTED BY NOW</span></div><button data-project="${i}">${people.filter((_,j)=>state.assign[j]===i).map(p=>p.n.split(' ')[0]).join(' + ')||'No engineers assigned'} · Edit staffing →</button></section>`).join('')}</div><div class="section-head"><span>ON-CALL ROTATION</span><span>THIS WEEK</span></div><div class="panel project"><label for="oncall">Primary engineer</label><select id="oncall" class="inline-select">${people.map((p,i)=>`<option value="${i}" ${state.oncall===i?'selected':''}>${p.n} · Debugging ${p.v[1]} · Energy ${p.v[5]}</option>`).join('')}</select><p class="helper">On call: ${people[state.oncall].n}. Debugging affects incidents. Energy affects recovery.</p></div><div class="section-head"><span>TEAM SYSTEMS</span></div><div class="panel"><div class="trust"><div class="score-line"><span>Tech Debt</span><b class="warn">38 / 100</b></div>${meter(38,'Tech Debt')}<p class="mini">Slows progress · raises incident risk</p></div><div class="trust"><div class="score-line"><span>On-call Load</span><b class="bad">62 / 100</b></div>${meter(62,'On-call Load')}<p class="mini">Drains the primary engineer’s Energy</p></div></div>`}
function assign(){return `${btn('← Projects','projects','back')}<h1>Staff ${projectsData[projectId][0]}.</h1><p class="subtitle">One primary project per engineer. Assignments are free; their time is not infinite.</p><div class="panel">${people.map((p,i)=>`<button class="intent ${state.assign[i]===projectId?'selected':''}" style="margin:0;border-width:0 0 1px;box-shadow:none" data-assign="${i}" aria-pressed="${state.assign[i]===projectId}"><span class="intent-main"><span>${p.n}</span><span>${state.assign[i]===projectId?'✓':'＋'}</span></span><span class="intent-hints">Coding ${p.v[0]} · Morale ${p.v[4]} · Energy ${p.v[5]}<br>${state.assign[i]===projectId?'Assigned here':`Move from ${projectsData[state.assign[i]][0]}`}</span></button>`).join('')}</div><p class="helper">Selecting moves the engineer from their current project. Tap an assigned engineer to move them to the next project in this prototype.</p>${btn('Done · review projects →','projects','primary')}`}
function office(){return `<div class="heading"><h1>Office politics.</h1><small>3 STAKEHOLDERS</small></div><p class="subtitle">Everyone is aligned. In different directions.</p><div class="stat-pair"><div><span class="eyebrow">YOUR STRESS</span><b class="${cost()>8?'bad':'warn'}">${42+Math.max(0,cost()-8)*5}<small class="mini"> / 100</small></b></div><div><span class="eyebrow">POLITICAL CAPITAL</span><b>${state.capital}<small class="mini"> PC</small></b></div></div><p class="helper">High Stress reduces next week’s available time. Extra-slot penalty shown here is an illustrative +5 per slot.</p><div class="section-head"><span>STAKEHOLDER TRUST</span><span>0–100</span></div><div class="panel">${[['Morgan Vale','Skip-level · “Show me the impact.”',64],['Jules Park','PM · “Can we squeeze this in?”',48],['Casey Lin','Peer EM · “Happy to take the credit.”',57]].map(p=>`<div class="trust"><div class="score-line"><b>${p[0]}</b><span class="num ${p[2]<50?'warn':'good'}">${p[2]}</span></div><p class="helper">${p[1]}</p>${meter(p[2],p[0]+' Trust')}</div>`).join('')}</div><div class="section-head"><span>SPEND YOUR CAPITAL</span></div><button class="intent" data-politics="scope" ${state.politics.includes('scope')||state.capital<8?'disabled':''}><span class="intent-main"><span>${state.politics.includes('scope')?'✓ Scope pushback secured':'Push back on extra scope'}</span><span class="cost">8 PC</span></span><span class="intent-hints">Delivery protected · PM Trust risk · 0 slots</span></button><button class="intent" data-politics="hire" ${state.politics.includes('hire')||state.capital<15?'disabled':''}><span class="intent-main"><span>${state.politics.includes('hire')?'✓ Headcount case reserved':'Fight for next quarter’s headcount'}</span><span class="cost">15 PC</span></span><span class="intent-hints">Hiring chance ↑ · Skip-level Trust risk · 0 slots</span></button><div class="section-head"><span>YOU OWE</span><span>FACT LEDGER</span></div><div class="panel promise"><b>Mei: a week off the pager.</b><p>Promised week 3 · Due week 5 · Open</p></div>${state.choices[0]===0?'<div class="panel promise"><b>Priya: promotion packet this cycle.</b><p>Promised this week · Due week 10 · Open</p></div>':''}`}
function fridayLines(bad){const on=people[state.oncall];return [['09:05','The plan is locked. The calendar has opinions.','Week '+state.week+' · '+cost()+'/8 slots booked'],['10:02',bad?'Checkout v2 misses its integration target. <b class="bad">Deadline at risk.</b>':'Checkout v2 clears integration. <b class="good">On track.</b>','Staffing → delivery'],['14:40',`PagerDuty fires. ${on.n.split(' ')[0]} is on call. A queue starts growing.`, `Debugging ${on.v[1]} · Energy ${on.v[5]}`],['15:15',bad?'The escalation reaches you. Three hours later, rollback. <b class="bad">Tech Debt +2.</b>':'The runbook works. Back to green in 18 minutes. <b class="good">On-call Load −4.</b>',bad?'On-call mismatch → longer recovery':'Rotation choice → quick recovery'],['16:20',state.choices[0]===0?'Priya gets the written commitment. <b class="good">Morale +3.</b>':state.choices[0]===1?'Priya appreciates the honesty. It still stings. <b class="bad">Morale −2.</b>':state.choices[0]===2?'Priya takes the technical lead. Her ambition has somewhere to go.':'Priya is still waiting for a conversation.','Your response → people outcome'],['17:30',state.choices[4]!==undefined&&state.choices[4]!=='ignore'?'The CEO asks for an update on the AI exploration.':'The CEO’s “quick ask” from Monday is quietly forgotten.','Ignored demand → resolved'],['17:52','Luck: a dependency arrives '+(bad?'late. One point lost.':'early. One point gained.'),'Small variance, separate from your decisions']];}
function friday(){const lines=fridayLines(fridayBad);return `<span class="eyebrow">WEEK ${state.week} / MATCH DAY</span><div class="friday-intro"><span class="live">${fridayCount>=lines.length?'FULL TIME':'COMMENTARY'}</span><h1>Friday, then.</h1><p class="subtitle">The part where the plan meets production.</p></div><div aria-live="polite" aria-relevant="additions">${lines.slice(0,fridayCount).map(l=>`<div class="commentary"><time>${l[0]}</time><p>${l[1]}<small>${l[2]}</small></p></div>`).join('')}</div>${screen==='loading'?'<div class="notice"><b>Monday’s copy is taking longer.</b><p>The week’s results are safe. Continue with template text; generated wording can arrive later.</p></div>':''}<div class="friday-actions">${fridayCount>=lines.length?btn('Read the back page →',fridayBad?'back-bad':'back-good','primary'):btn('Show all commentary ↓','skip')}${screen==='loading'?btn('Use template text →','back-good'):''}</div>`}
function backpage(bad){return `<div class="paper"><div class="masthead">The Engineering Post</div><div class="paper-date">Q1 2027 · WEEK ${state.week} · THE FRIDAY EDITION</div><h1>${bad?'Everything was on fire.<br>Including the roadmap.':'A release.<br>A runbook.<br>A small victory.'}</h1><p class="recap">${bad?'Checkout slipped. The pager escalated. “Let’s take the learnings into next week,” said the person who requested the extra scope.':'Checkout moved forward and the pager met a prepared engineer. Nobody mentioned the AI button. For one Friday, that counts.'}</p><div class="section-head"><span>THE NUMBERS / AND THE WHY</span></div>${(bad?[['↑ 2','bad','Tech Debt','Three-hour rollback after the on-call escalation.'],['↓ 4','bad','Dana’s Energy','Incident recovery on an already depleted rotation.'],['↓ 6','bad','PM Trust','Checkout missed its integration target.']]:[['↑ 8','good','Checkout progress','Assigned engineers cleared integration.'],['↓ 4','good','On-call Load','Prepared rotation contained the incident.'],['↑ 3','good','PM Trust','The demo stayed on track.']]).map(d=>`<div class="delta"><b class="${d[1]}">${d[0]}</b><div><strong>${d[2]}</strong><small>${d[3]}</small></div></div>`).join('')}${state.choices[0]===0?'<div class="delta"><b class="good">↑ 3</b><div><strong>Priya’s Morale</strong><small>Written promotion commitment. Promise due week 10.</small></div></div>':''}<div class="delta"><b class="${bad?'bad':'good'}">${bad?'−':'+'} 1</b><div><strong>Luck / dependency timing</strong><small>Variance contribution to delivery, not a hidden choice effect.</small></div></div><p class="helper" style="margin:16px 0">Results here are illustrative outcome designs, not a full simulation.</p>${btn(state.week===5?'Mid-quarter check-in →':state.week===12?'Quarterly review →':`Monday · week ${state.week+1} →`,'next','primary')}</div>`}
function checkin(){return `<span class="eyebrow">WEEK 6 / MID-QUARTER</span><h1 style="margin-top:12px">“How do you think<br>it’s going?”</h1><div class="sender"><span class="avatar">MV</span><div><b>Morgan Vale</b><small>Your skip-level · 25 minutes booked</small></div></div><div class="review-letter"><p>“Checkout is moving. Good. But Dana can’t be the fallback plan for every incident.</p><p>“By the end of the quarter I want two things: the migration on track, and an on-call rotation that doesn’t need a recovery week.”</p></div><div class="section-head"><span>THE REVIEW LENS</span><span>NO RATING YET</span></div><div class="panel"><div class="why"><b>Delivery · 40%</b><small>Checkout on track; migration behind.</small></div><div class="why"><b>Team health · 30%</b><small>Dana’s Energy is the main risk.</small></div><div class="why"><b>Stakeholder Trust · 30%</b><small>Keep promises visible. Don’t optimize only for Morgan.</small></div></div><div class="section-head"><span>SET A FOCUS / NO SLOT COST</span></div>${['Protect the rotation','Recover the migration'].map((t,i)=>`<button class="intent ${state.checkin===i?'selected':''}" data-checkin="${i}" aria-pressed="${state.checkin===i}"><b>${state.checkin===i?'✓ ':''}${t}</b><span class="intent-hints">Personal planning reminder · no hidden stat bonus</span></button>`).join('')}${btn('Back to planning · week 6 →','checkin-done','primary')}`}
function review(){return `<span class="eyebrow">WEEK 12 / CONFIDENTIAL</span><h1 style="margin-top:10px">Quarterly review.</h1><p class="subtitle">Morgan Vale · Engineering management · Q1 2027</p><div class="review-letter"><p>“You shipped the release without making the team pay for it every weekend. That matters.</p><p>“The migration still needed rescuing. And ‘I’ll get to the promo packet’ is not a succession plan.</p><p>“A good quarter. Now make it repeatable.”</p></div>${state.reviewOpen?`<section class="rating"><span class="eyebrow">FINAL RATING</span><h2>Exceeds expectations.</h2><p class="helper">You delivered. Your team is still here to deliver again.</p></section><div class="rating-lines"><span>Delivery · 40%</span><b>82 / 100</b><span>Team health · 30%</span><b>76 / 100</b><span>Stakeholder Trust · 30%</span><b>71 / 100</b><span>Weighted result</span><b>76.9 / 100</b><span>Boss adjustment</span><b>0 steps</b></div><p class="helper" style="margin:18px 0">Sample grade. Final thresholds and career outcomes remain open design decisions.</p>${btn('Archive quarter · return to title','title','primary')}<p class="helper">Career continuation can attach here without adding a fifth planning tab.</p>`:`<div class="rating"><span class="eyebrow">THE VERDICT IS READY</span><h2>One quarter.<br>One conversation.</h2></div>${btn('Open your rating →','reveal','primary')}`}`}
function title(){return `<div class="title-art"><img src="artwork/app-icon.svg" alt="Eight calendar blocks, one overbooked"><span class="eyebrow">SEASON 2027</span><h1>EM27</h1><h2>ENGINEERING MANAGER</h2></div><p class="title-tagline">Six engineers.<br>Eight slots.<br>“Got a quick minute?”</p><p class="subtitle">Pick your company. Survive the calendar.</p><div class="section-head"><span>CHOOSE YOUR DUGOUT</span></div>${[['Vercel','Startup · Launches before breathing'],['Stripe','Scale-up · Please write the doc'],['Google','Big tech · Align on the alignment']].map(p=>`<button class="company-option ${state.company===p[0]?'selected':''}" data-company="${p[0]}" aria-pressed="${state.company===p[0]}">${badge(p[0])}<span><b>${p[0]}</b><small>${p[1]}</small></span><span>${state.company===p[0]?'●':'○'}</span></button>`).join('')}${btn('Start a career →','newgame','primary')}${saved?`<button class="secondary" data-action="resume" style="margin-top:10px">Continue saved plan · week ${state.week}</button>`:''}<p class="disclaimer">Parody. Not affiliated with or endorsed by any company named. All characters and situations are fictional.<br><br>No sign-in. Your save stays on this device.</p>`}
function kit(){return `<span class="eyebrow">EM27 / COMPONENT LIBRARY</span><h1 style="margin-top:8px">The numbers game.</h1><p class="subtitle">Practical, legible, slightly institutional.</p><div class="section-head"><span>01 / TYPE</span></div><h2 style="font-size:26px;letter-spacing:-.8px">The week ahead.</h2><p style="margin:10px 0">Tahoma / Arial · 14px decision copy.</p><p class="mini">CM TABLE NUMBERS / 10–17PX / 0123456789</p><div class="section-head"><span>02 / SEMANTIC COLOR</span></div><div class="kit-swatch"><span style="background:var(--bar);color:var(--on-bar)">BLUE</span><span style="background:var(--accent-soft);color:var(--accent)">YELLOW</span><span style="background:var(--bad-soft);color:var(--bad)">RISK !</span><span style="background:var(--good-soft);color:var(--good)">GAIN ↑</span></div><div class="section-head"><span>03 / ATTRIBUTES</span><span>1–20</span></div><div class="panel range">${Array.from({length:20},(_,i)=>num(i+1)).join('')}</div><p class="helper">1–7 low · 8–13 capable · 14–20 strong. Color reinforces the numeric value.</p><div class="section-head"><span>04 / INTENT</span><span>MIN 44PX</span></div><button class="intent" data-action="demo"><span class="intent-main"><span>Commit to the promo, in writing</span><span class="cost">1 slot</span></span><span class="intent-hints">Morale ↑ · Promise due wk 10</span></button><button class="intent selected" data-action="demo"><span class="intent-main"><span>✓ Book a proper check-in</span><span class="cost">1 slot</span></span><span class="intent-hints">Energy ↑ · Morale ↑</span></button><button class="secondary" disabled>Ignore unavailable · must respond</button><div class="section-head"><span>05 / METERS & CAUSES</span></div>${meter(64,'Example Trust')}<div class="delta"><b class="bad">↓ 3</b><div><strong>Morale</strong><small>Promo deferred · week 2</small></div></div><div class="section-head"><span>06 / GENERIC COMPANY BADGES</span></div><div style="display:flex;gap:12px;flex-wrap:wrap">${['Vercel','Stripe','Google'].map(n=>`<span>${badge(n)} ${n}</span>`).join('')}</div><div class="section-head"><span>07 / FEEDBACK STATES</span></div><div class="notice success">✓ Booked. You can change this until Friday.</div><div class="notice danger">! 2 slots over budget. Continue is still available.</div><div class="notice">Text is delayed. Your results are safe.</div>`}
function show(next){clearInterval(fridayTimer);screen=next;if(next==='event')eventId=0;if(next==='long')eventId=0;if(next==='ignored'){eventId=4;state.choices[4]='ignore';save()}if(next==='overbooked'){state.choices={0:0,1:2,2:0,3:0,4:2,5:0};save()}if(next==='empty'){state.choices={0:0,1:0,2:2,3:0,4:'ignore',5:'ignore'};save()}if(next==='checkin'){state.week=6;save()}if(next==='review'){state.week=12;save()}if(next.startsWith('friday')||next==='loading'){fridayBad=next==='friday-bad';fridayCount=next==='loading'?7:0;startTimer()}render();window.scrollTo({top:0,behavior:'instant'})}
function startTimer(){clearInterval(fridayTimer);if(fridayCount<7)fridayTimer=setInterval(()=>{if(!document.hidden){fridayCount++;render();if(fridayCount>=7)clearInterval(fridayTimer)}},1600)}
function render(){const planning=['week','empty','overbooked','event','long','ignored','squad','player','projects','assign','office','kit'].includes(screen);let content=screen==='week'||screen==='overbooked'?week():screen==='empty'?week(true):['event','long','ignored'].includes(screen)?eventView(screen==='long'):screen==='squad'?squad():screen==='player'?player():screen==='projects'?projects():screen==='assign'?assign():screen==='office'?office():screen==='title'?title():screen==='checkin'?checkin():screen==='review'?review():screen==='kit'?kit():screen.startsWith('back')?backpage(screen==='back-bad'):friday();$('#app').innerHTML=screen==='splash'?`<div class="splash"><img src="artwork/app-icon.svg" alt="EM27 calendar symbol"><h1>EM27</h1><p>ENGINEERING MANAGER</p><small>Eight slots. Good luck.</small></div>`:`${header()}${planning?calendar():''}<main id="main" tabindex="-1">${content}</main>${planning?dock():''}`;$('#screen-picker').value=screen;$('#theme-button').textContent=theme==='light'?'Switch to dark theme ◐':'Switch to light theme ◑'}
$('#screen-picker').innerHTML=Object.entries(screens).map(([id,label])=>`<option value="${id}">${label}</option>`).join('');
$('#screen-picker').addEventListener('change',e=>show(e.target.value));
$('#theme-button').addEventListener('click',()=>{theme=theme==='light'?'dark':'light';document.documentElement.dataset.theme=theme;try{localStorage.setItem('em27.design.theme',theme)}catch(e){}render()});
document.addEventListener('change',e=>{if(e.target.id==='oncall'){state.oncall=Number(e.target.value);save();render();notify('On-call rotation updated · no slots spent')}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;if(d.screen){show(d.screen);return}if(d.event!==undefined){eventId=Number(d.event);screen='event';render();$('#main').focus({preventScroll:true});return}if(d.choice!==undefined){const old=cost();state.choices[eventId]=d.choice==='ignore'?'ignore':Number(d.choice);save();render();notify(d.choice==='ignore'?'Ignored · resolves Friday':`${cost()>old?'Booked':'Plan updated'} · ${cost()}/8 slots${cost()>8?' · overbooking adds Stress':''}`);return}if(d.person!==undefined){personId=Number(d.person);show('player');return}if(d.book!==undefined||d.unbook!==undefined){const id=d.book??d.unbook;state.books[id]=!state.books[id];save();render();notify(state.books[id]?'1:1 booked · 1 slot spent':'1:1 removed · 1 slot refunded');return}if(d.oncall!==undefined){state.oncall=Number(d.oncall);save();render();notify('On-call rotation updated');return}if(d.project!==undefined){projectId=Number(d.project);show('assign');return}if(d.assign!==undefined){const id=Number(d.assign);state.assign[id]=state.assign[id]===projectId?(projectId+1)%projectsData.length:projectId;save();render();notify('Assignment updated · no slots spent');return}if(d.company){state.company=d.company;render();return}if(d.politics){const pc=d.politics==='scope'?8:15;if(state.capital<pc)return;state.capital-=pc;state.politics.push(d.politics);save();render();notify(`${pc} Political Capital reserved · sample action`);return}if(d.checkin!==undefined){state.checkin=Number(d.checkin);save();render();return}const a=d.action;if(!a)return;if(a==='player-profile'){$('main').scrollTop=0}else if(a==='player-history'||a==='player-actions'){$('#'+a).scrollIntoView({block:'start',behavior:'smooth'})}else if(a==='focus'){state.focus=!state.focus;save();render();notify(state.focus?'Focus time booked · Stress ↓':'Focus time refunded · 1 slot returned')}else if(a==='continue'){if(required()){eventId=0;screen='event';render();notify('Priya needs a response before you lock the week.')}else show(state.oncall===2?'friday-bad':'friday-good')}else if(a==='agenda'){$('#agenda')?$('#agenda').scrollIntoView({block:'center',behavior:'smooth'}):show('week')}else if(a==='skip'){fridayCount=7;clearInterval(fridayTimer);render()}else if(a==='next'){if(state.week===5)show('checkin');else if(state.week===12)show('review');else{state.week=Math.min(12,state.week+1);state.choices={};state.books={};state.focus=false;state.postmortem=false;save();show('week')}}else if(a==='reveal'){state.reviewOpen=true;save();render()}else if(a==='checkin-done'){state.week=6;save();show('week')}else if(a==='newgame'){state={...defaults(),week:1,company:state.company,choices:{},books:{}};save();show('week');notify('New sample quarter · your team is ready')}else if(a==='resume')show('week');else if(a==='demo')notify('Intent button specimen · see Event screen to book');else if(screens[a])show(a)});
const initialScreen=new URLSearchParams(location.search).get('screen');
if(initialScreen&&Object.hasOwn(screens,initialScreen))show(initialScreen);else render();
